pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, uint256 blockNum) public {
        // Restrict value to admissible domain: any msg.value
        // Bound blockNum to avoid overflow, but keep wide range
        blockNum = bound(blockNum, 1, type(uint256).max - 1);
        vm.assume(value != 10 ether);

        // Ensure contract has a balance to observe transfer behavior
        vm.deal(address(c), 10 ether);

        // Set block number to control transfer condition
        vm.roll(blockNum);
        // Ensure timestamp increases to pass require
        vm.warp(block.timestamp + 1);

        address sender = address(0x1234);
        vm.deal(sender, value);
        vm.prank(sender);
        bool ok;
        try c.fallback{value: value}() { ok = true; } catch { ok = false; }

        // Assert: if the call succeeded (ok == true), then the entire contract balance must have been transferred.
        // On the reference, ok is always false for value != 10 ether, so the implication holds vacuously.
        // On the mutant, value == 0 ether succeeds, but the transfer only triggers if blockNum % 15 == 0.
        // When blockNum % 15 != 0, the balance remains > 0, violating the invariant.
        assertTrue(!ok || address(c).balance == 0);
    }
}

