pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint48 blockNum) public {
        // The fallback requires msg.value == 10 ether in the reference,
        // so only 10 ether is admissible for a non-reverting call.
        // We donate 10 ether to establish a non-zero balance.
        vm.deal(address(this), 10 ether);
        (bool ok,) = address(c).call{value: 10 ether}("");
        require(ok, "initial donation failed");

        // Fuzz a new block number, making sure it's different from the donation
        // block, and a msg.value to send via the fallback.
        vm.roll(uint256(blockNum));
        // Advance timestamp so block.timestamp > pastBlockTime (from donation).
        vm.warp(block.timestamp + 1);

        // Bring the caller's balance high enough for any fuzzed amount.
        vm.deal(address(this), amount);
        bool success;
        try c.fallback{value: amount}() { success = true; } catch { success = false; }

        if (success) {
            // Rule: after a successful call the contract balance must be zero.
            assertTrue(address(c).balance == 0, "non-reverting fallback left non-zero balance");
        } else {
            // Reverting calls are not constrained by this property.
            assertTrue(true);
        }
    }
}

