contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 nonce1, uint256 nonce2, uint256 nonce3) public {
        // Bind block timestamps to strictly increasing values
        uint256 t1 = bound(nonce1, 0, type(uint64).max);
        uint256 t2 = bound(nonce2, t1 + 1, type(uint64).max);
        uint256 t3 = bound(nonce3, t2 + 1, type(uint64).max);

        // Determine block numbers that guarantee one of them is divisible by 15
        // We set block numbers to 1, 2, and 15 to ensure the third call triggers transfer
        // The fuzzer still controls timestamps, keeping wide input space

        // First valid fallback call
        vm.deal(address(this), 100 ether);
        vm.warp(t1);
        vm.roll(1);
        vm.prank(address(this));
