// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 call1_block, uint256 call2_block) public {
        // Restrict to admissible domain: block numbers within a reasonable range and timestamps must increase
        vm.assume(call1_block > 0 && call1_block < 1e9);
        vm.assume(call2_block > call1_block && call2_block < 1e9);
        // Timestamps must be > 0 and increase between calls
        uint256 time1 = call1_block * 1e3; // simple deterministic mapping
        uint256 time2 = call2_block * 1e3;
        vm.assume(time2 > time1);

        // Setup: deploy helper that will receive the transferred balance
        address payable helper = payable(new BalanceReceiver());

        // First call: use block number that is NOT a multiple of 15, so in buggy version pastBlockTime is NOT updated
        vm.assume(call1_block % 15 != 0);
        vm.deal(address(this), 10 ether);
        vm.roll(call1_block);
        vm.warp(time1);
        // We need a call that goes through. The fallback requires block.timestamp > pastBlockTime (initially 0)
        // and msg.value == 10 ether. It will not transfer because block.number % 15 != 0.
        (bool ok1,) = address(c).call{value: 10 ether}("");
        require(ok1, "call1 failed");

        // Second call: use block number that IS a multiple of 15
        vm.assume(call2_block % 15 == 0);
        vm.deal(address(this), 10 ether);
        vm.roll(call2_block);
        vm.warp(time2);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        require(ok2, "call2 failed");

        // After the second call, the contract balance must be zero.
        // In the correct version, pastBlockTime was updated in the first call,
        // so the second call sees time has passed since the last update and transfers the entire balance.
        // In the buggy version, pastBlockTime was NOT updated in the first call,
        // so the second call still compares against the initial pastBlockTime (0),
        // time2 > 0 is true, but the transfer condition (block.number % 15 == 0) triggers
        // and transfers the balance (20 ether). However, the bug only fails to update pastBlockTime
        // when not transferring; the invariant check is balance zero after any non-reverting call.
        // Wait: In buggy, first call doesn't update pastBlockTime (stays 0). Second call:
        // require(time2 > 0) passes. block.number % 15 == 0 -> updates pastBlockTime and transfers ALL balance.
        // So after second call balance is 0. That doesn't break.
        // We need a sequence where the bug leaves a non-zero balance.
        // Actually, let's reconsider: the correct version always updates pastBlockTime.
        // The invariant "after every fallback call, pastBlockTime equals the block.timestamp of that call"
        // is violated by the buggy version.
        // But we need a rule observable from public surface.
        // pastBlockTime is a public state variable with a getter.
        // Rule: After any non-reverting call to fallback(), pastBlockTime must equal the block.timestamp of that call.
        // In buggy version, if block.number % 15 != 0, pastBlockTime is not updated, so it retains old value,
        // breaking the rule.
        // But we were told not to repeat already-tried approaches: "After any call to fallback() that sends Ether, pastBlockTime must equal the block.timestamp of that call..."
        // and "pastBlockTime strictly increases". Both already tried.
        // We need a different property that still fails for the buggy version.
        // Let's think about the contract balance. In correct version, after ANY call where block.number % 15 == 0,
        // the entire balance is transferred, so balance becomes 0.
        // In buggy version, if there was a previous call that did NOT update pastBlockTime, then a subsequent call
        // with block.number % 15 == 0 will see pastBlockTime = old timestamp (e.g., 0 from constructor) and
        // require(time > old) will pass, so it will transfer the entire balance.
        // Wait, buggy version: pastBlockTime only updated inside if block. So after a non-multiple call, pastBlockTime unchanged.
        // Then later a multiple call comes, pastBlockTime is still old, timestamp > old, so it transfers entire balance.
        // Balance becomes 0. So balance invariant might still hold.
        // But what if a call fails? No, require(msg.value == 10 ether) fails.
        // Another angle: the bug makes pastBlockTime become stale, so a subsequent call might fail the require(timestamp > pastBlockTime) check if the timestamp hasn't increased beyond the last actual update.
        // For example: call1 (non-multiple, time=100) -> no update, pastBlockTime remains 0.
        // call2 (non-multiple, time=50, but time must be > 0, so it passes) -> no update.
        // call3 (multiple, time=200) -> passes, updates pastBlockTime=200, transfers.
        // This doesn't cause a revert.
        // To cause a revert difference: suppose we have two calls where the second call's timestamp is less than or equal to the pastBlockTime that was last updated.
        // In correct version, after call1 (time=100), pastBlockTime=100. Then call2 with time=100 or 101? time must be > 100 to pass. If time=101, it passes.
        // In buggy version, after call1 (time=100, non-multiple), pastBlockTime stays 0. Then call2 with time=50 (but >0) would pass in buggy, but would revert in correct because time=50 is not > pastBlockTime=100.
        // So invariant: "A call with a timestamp less than a previously seen timestamp in any successful call must revert."
        // But the buggy version allows it, breaking a security property.
