contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 nonTransferBlock, uint256 transferBlock, uint256 timestamp) public {
        // nonTransferBlock must not be divisible by 15, transferBlock must be divisible by 15
        vm.assume(nonTransferBlock > 0);
        vm.assume(transferBlock > nonTransferBlock);
        vm.assume(transferBlock % 15 == 0);
        vm.assume(nonTransferBlock % 15 != 0);
        // Use a single, fixed timestamp for both calls
        vm.assume(timestamp > 0);

        // First call: non-transfer, sets pastBlockTime to timestamp
        vm.roll(nonTransferBlock);
        vm.warp(timestamp);
        vm.deal(address(this), 10 ether);
        // Use a low-level call to catch revert
        (bool ok1,) = address(c).call{value: 10 ether}("");
        // First call should succeed in reference; in bug it also succeeds, but pastBlockTime not updated

        // Second call: transfer-triggering block, same timestamp
        vm.roll(transferBlock);
        vm.warp(timestamp);
        vm.deal(address(this), 10 ether);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // Reference: second call reverts because timestamp == pastBlockTime (strictly greater check fails)
        // Bug: pastBlockTime was not updated on first call (still 0 or old value), so timestamp > pastBlockTime passes, call succeeds
        // Property: if timestamp equals previous block's timestamp after a non-transfer call, the call must revert.
        assertTrue(!ok2);
    }
}

