pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 fuzzAmount, uint8 fuzzBlocks) public {
        vm.assume(fuzzAmount == 10 ether);
        vm.assume(fuzzBlocks >= 1 && fuzzBlocks <= 100);

        // Prepare sender
        address sender = makeAddr("sender");
        vm.deal(sender, 1000 ether);

        // Make a first call to set pastBlockTime
        vm.prank(sender);
        (bool success1,) = address(c).call{value: 10 ether}("");
        assertTrue(success1);

        uint256 lastStored = c.pastBlockTime();

        // Advance by fuzzBlocks (at least 1)
        vm.roll(block.number + fuzzBlocks);
        // Warp to the same last stored timestamp to test the invariant tightly
        vm.warp(lastStored);

        vm.prank(sender);
        (bool success2,) = address(c).call{value: 10 ether}("");

        // Second call must fail because block.timestamp == lastStored, but M set lastStored to block.timestamp+1 in first call,
        // making the require(block.timestamp > pastBlockTime) fail.
        // The reference allowed equal timestamps because it stored exactly block.timestamp.
        assertTrue(!success2);
    }
}

